 "content": "def transform(grid):
    """Extend bottom vertical rays upward through aligned horizontal bars.

    Each crossing gap is filled with that bar's color. Between successive
    bars, the vertical segment takes the lower bar's color; above the top bar
    it takes the top bar's color. Keep the original vertical ray below the
    last crossing.
    """
    out = [row[:] for row in grid]
    h, w = len(out), len(out[0])
    marker_cols = [c for c in range(w) if out[h - 1][c] != 0]
    for c in marker_cols:
        bars = []
        for r in range(h):
            if out[r][c] != 0 or c == 0 or c == w - 1:
                continue
            left, right = out[r][c - 1], out[r][c + 1]
            if left != 0 and left == right:
                bars.append((r, left))
        if not bars:
            continue
        # Above the first bar, use its color.
        first_r, first_color = bars[0]
        for r in range(first_r + 1):
            if out[r][c] == 0:
                out[r][c] = first_color
        # Between bars, the lower bar supplies the color.
        for (prev_r, _), (r, color) in zip(bars, bars[1:]):
            for rr in range(prev_r + 1, r + 1):
                if out[rr][c] == 0:
                    out[rr][c] = color
    return out
