    out = [row[:] for row in grid]
    h, w = len(out), len(out[0])
    # Bottom-edge vertical markers select the columns whose horizontal gaps
    # are connected upward. Each horizontal bar colors the segment above it.
    for c in range(w):
        if out[h - 1][c] == 0:
            continue
        crossings = []
        for r in range(h):
            if 0 < c < w - 1 and out[r][c] == 0:
                color = out[r][c - 1]
                if color != 0 and color == out[r][c + 1]:
                    crossings.append((r, color))
        if not crossings:
            continue
        # Extend the highest bar's color to the top; each subsequent bar
        # changes the vertical color from just below the previous crossing.
        start = 0
        for r, color in crossings:
            for rr in range(start, r + 1):
                out[rr][c] = color
            start = r + 1
    return out
